window.MY_WASM_BASE64 = "";

function base64ToUint8Array(base64) {
    var binary_string = window.atob(base64);
    var len = binary_string.length;
    var bytes = new Uint8Array(len);
    for (var i = 0; i < len; i++) {
        bytes[i] = binary_string.charCodeAt(i);
    }
    return bytes;
}

// Létrehozzuk a Module objektumot a memóriában lévő bájtokkal
window.Module = {
    wasmBinary: base64ToUint8Array(window.MY_WASM_BASE64)
};
